// WF08 analysis_runs ledger writer (Stage 3 closure, DEC-148). One row per SELECTED source record = the
// exactly-once idempotency key the next run reads back. Runs once per WF08 execution. No external calls.
function str(v){return v==null?'':String(v).trim();}
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
const cfg=$('Set Analyzer Config').first().json||{};
const sel=$('Filter & Select Records').all().map(function(i){return i.json;});
const now=moscowIsoNow();
return sel.map(function(r){ var sid=str(r.source_run_id), rid=str(r.source_record_id)||str(r.record_id);
  return { json: {
    analysis_run_id:str(r.analysis_run_id)||str(cfg.analysis_run_id),
    analysis_idempotency_key:str(r.analysis_idempotency_key)||(sid+'::'+rid),
    source_run_id:sid, source_record_id:rid, agent_request_id:str(r.agent_request_id),
    platform:str(r.platform), source_type:str(r.source_type), data_mode:str(r.data_mode)||'live',
    analysis_status:'analyzed', analyzed_at:now, analysis_mode:str(cfg.analysis_mode), llm_used:false,
    notes:'wf08 analysis ledger (exactly-once)'
  }};
});
